Here is a C++ function that takes a reference to a `std::string` containing markdown formatted text and returns a `std::string` containing HTML formatted text:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::stringstream ss(markdown);
    std::string line;
    while (std::getline(ss, line)) {
        html += line;
    }
    // Convert Markdown to HTML
    std::regex regex(R"(#(\w+)\n)");
    std::regex_replace(html, regex, R"<h1>$1</h1>\n");
    return html;
}

int main() {
    std::string markdown = "# Sample\nThis is a sample text.\n# Example\nThis is an example text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a regular expression to replace Markdown headings with HTML tags. The regular expression matches the pattern `#(\w+)\n` and replaces it with `<h1>$1</h1>\n`. The rest of the Markdown text is left unchanged.

